const getPreviousSettlementBalance = `-- name: GetPreviousSettlementBalance :one
SELECT COALESCE(net_amount_minor - paid_minor, 0)::bigint AS carry_forward_minor,
       settlement_number, period_end
FROM settlements
WHERE organization_id = $1 AND franchise_id = $2
  AND period_end < $3::date
  AND status IN ('APPROVED','PARTIALLY_PAID','PAID','CLOSED')
ORDER BY period_end DESC, id DESC
LIMIT 1
`

type GetPreviousSettlementBalanceParams struct {
	OrganizationID int64
	FranchiseID    int64
	Before         time.Time
}

type GetPreviousSettlementBalanceRow struct {
	CarryForwardMinor int64
	SettlementNumber  string
	PeriodEnd         time.Time
}

// The closing position of the franchise's most recent settled statement, which
// becomes this one's opening balance. Unpaid amounts carry forward rather than
// being forgotten.
func (q *Queries) GetPreviousSettlementBalance(ctx context.Context, arg GetPreviousSettlementBalanceParams) (GetPreviousSettlementBalanceRow, error) {
	row := q.db.QueryRow(ctx, getPreviousSettlementBalance, arg.OrganizationID, arg.FranchiseID, arg.Before)
	var i GetPreviousSettlementBalanceRow
	err := row.Scan(&i.CarryForwardMinor, &i.SettlementNumber, &i.PeriodEnd)
	return i, err
}

